<?php
if (!defined('ABSPATH')) exit;
/** Standards-based Web Push: VAPID ES256 and RFC 8291 aes128gcm. */
final class Dares_Piket_Push {
 const OPT='dares_piket_push_opts';
 static function init(){add_filter('cron_schedules',[__CLASS__,'schedule']);add_action('init',[__CLASS__,'install']);add_action('rest_api_init',[__CLASS__,'routes']);add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_dares_piket_push_settings',[__CLASS__,'save']);add_action('dares_piket_push_tick',[__CLASS__,'tick']);add_action('dares_piket_push_queue',[__CLASS__,'send_event'],10,4);}
 static function table(){global $wpdb;return $wpdb->prefix.'dares_piket_push_subscriptions';}
 static function install(){if(get_option('dares_piket_push_db')==='2.2.0')return; global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();dbDelta('CREATE TABLE '.self::table().' (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,user_id bigint(20) unsigned NOT NULL,endpoint_hash char(64) NOT NULL,endpoint text NOT NULL,p256dh varchar(255) NOT NULL,auth varchar(255) NOT NULL,created_at datetime NOT NULL,PRIMARY KEY  (id),UNIQUE KEY endpoint_hash (endpoint_hash),KEY user_id (user_id)) '.$c);update_option('dares_piket_push_db','2.2.0',false);if(!wp_next_scheduled('dares_piket_push_tick'))wp_schedule_event(time()+120,'dares_piket_push_5min','dares_piket_push_tick');}
 static function schedule($a){$a['dares_piket_push_5min']=['interval'=>300,'display'=>'DARES push iedere 5 minuten'];return $a;}
 static function opts(){return wp_parse_args((array)get_option(self::OPT,[]),['enabled'=>0,'reminder_hours'=>24,'start'=>1,'reminder'=>1,'changes'=>1,'transfer'=>1,'contact'=>'']);}
 static function save(){if(!current_user_can('manage_options'))wp_die('Geen toegang');check_admin_referer('dares_piket_push_settings');$o=self::opts();foreach(['enabled','start','reminder','changes','transfer'] as $key)$o[$key]=empty($_POST[$key])?0:1;$o['reminder_hours']=min(168,max(1,absint($_POST['reminder_hours']??24)));$o['contact']=sanitize_email(wp_unslash($_POST['contact']??''));update_option(self::OPT,$o,false);wp_safe_redirect(admin_url('admin.php?page=dares-piket-push&saved=1'));exit;}
 static function menu(){add_submenu_page('dares-piketrooster','PWA pushmeldingen','PWA pushmeldingen','manage_options','dares-piket-push',[__CLASS__,'admin']);}
 static function admin(){if(!current_user_can('manage_options'))wp_die('Geen toegang');global $wpdb;$o=self::opts();$total=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.self::table());echo '<div class="wrap"><h1>DARES PWA — Pushmeldingen</h1><p>Toestellen met abonnement: <strong>'.(int)$total.'</strong>. Push werkt uitsluitend op HTTPS en wanneer de medewerker zelf op het toestel toestemming geeft.</p>';if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Instellingen opgeslagen.</p></div>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dares_piket_push_settings">';wp_nonce_field('dares_piket_push_settings');foreach(['enabled'=>'Pushmeldingen inschakelen','start'=>'Dienst begint','reminder'=>'Herinnering voor piketdienst','changes'=>'Roosterwijzigingen (ook nieuwe diensten)','transfer'=>'Handmatige overdrachten'] as $key=>$label)echo '<p><label><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked($o[$key],1,false).'> '.esc_html($label).'</label></p>';echo '<p>Herinnering vóór aanvang: <input type="number" name="reminder_hours" min="1" max="168" value="'.esc_attr($o['reminder_hours']).'"> uur</p><p>VAPID contactmail: <input type="email" name="contact" value="'.esc_attr($o['contact']).'" placeholder="beheer@voorbeeld.nl"></p><button class="button button-primary">Opslaan</button></form><hr><p><strong>Test:</strong> open het PWA-portaal op je telefoon, log in en klik op Meldingen inschakelen en Testmelding. Een systeemcron voor wp-cron.php voorkomt vertragingen bij weinig websiteverkeer.</p><p>VAPID-sleutels blijven op de server opgeslagen. Bij sleutelvervanging moeten alle toestellen zich opnieuw abonneren.</p></div>';}
 static function b64($x){return rtrim(strtr(base64_encode($x),'+/','-_'),'=');}
 static function decode($x){if(!is_string($x)||!preg_match('/^[A-Za-z0-9_-]+$/D',$x))return false;return base64_decode(strtr($x,'-_','+/').str_repeat('=',(4-strlen($x)%4)%4),true);}
 static function keypair(){ $saved=get_option('dares_piket_push_vapid');if(is_array($saved)&&isset($saved['public'],$saved['private']))return $saved;if(!function_exists('openssl_pkey_new'))return null;$key=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);if(!$key)return null;openssl_pkey_export($key,$private);$info=openssl_pkey_get_details($key);if(empty($info['ec']['x'])||empty($info['ec']['y']))return null;$pub="\x04".$info['ec']['x'].$info['ec']['y'];$value=['public'=>self::b64($pub),'private'=>$private];update_option('dares_piket_push_vapid',$value,false);return $value;}
 static function routes(){register_rest_route('dares-piket/v1','/push/key',['methods'=>'GET','permission_callback'=>[__CLASS__,'permission'],'callback'=>function(){if(!self::opts()['enabled']||!Dares_Piket_PWA::active())return new WP_Error('inactive','Push staat uit',['status'=>403]);$k=self::keypair();return $k?rest_ensure_response(['key'=>$k['public']]):new WP_Error('crypto','OpenSSL P-256 ontbreekt',['status'=>500]);}]);register_rest_route('dares-piket/v1','/push/subscription',['methods'=>['POST','DELETE'],'permission_callback'=>[__CLASS__,'permission'],'callback'=>[__CLASS__,'subscription']]);register_rest_route('dares-piket/v1','/push/test',['methods'=>'POST','permission_callback'=>[__CLASS__,'permission'],'callback'=>[__CLASS__,'test']]);}
 static function permission(){return is_user_logged_in();}
 static function subscription($request){global $wpdb;$uid=get_current_user_id();$payload=$request->get_json_params();$endpoint=isset($payload['endpoint'])&&is_string($payload['endpoint'])?$payload['endpoint']:'';if(strlen($endpoint)<15||strlen($endpoint)>2000||!wp_http_validate_url($endpoint)||strpos($endpoint,'https://')!==0)return new WP_Error('invalid','Ongeldige endpoint',['status'=>400]);$host=wp_parse_url($endpoint,PHP_URL_HOST);$trusted=($host==='fcm.googleapis.com'||$host==='updates.push.services.mozilla.com'||$host==='web.push.apple.com'||preg_match('/\.push\.apple\.com$/',$host)||$host==='wns2-par02p.notify.windows.com'||preg_match('/\.notify\.windows\.com$/',$host)||preg_match('/\.googleapis\.com$/',$host));if(!$trusted)return new WP_Error('host','Pushprovider niet toegestaan',['status'=>400]);$hash=hash('sha256',$endpoint);if($request->get_method()==='DELETE'){$wpdb->delete(self::table(),['endpoint_hash'=>$hash,'user_id'=>$uid]);return rest_ensure_response(['ok'=>true]);}if(!self::opts()['enabled']||!Dares_Piket_PWA::active())return new WP_Error('inactive','Push staat uit',['status'=>403]);$keys=$payload['keys']??[];$dh=self::decode($keys['p256dh']??'');$auth=self::decode($keys['auth']??'');if($dh===false||strlen($dh)!==65||$dh[0]!=="\x04"||$auth===false||strlen($auth)!==16)return new WP_Error('keys','Ongeldige sleutels',['status'=>400]);$wpdb->replace(self::table(),['user_id'=>$uid,'endpoint_hash'=>$hash,'endpoint'=>$endpoint,'p256dh'=>$keys['p256dh'],'auth'=>$keys['auth'],'created_at'=>current_time('mysql')]);return rest_ensure_response(['ok'=>true]);}
 static function test(){if(!self::opts()['enabled'])return new WP_Error('disabled','Uitgeschakeld',['status'=>403]);$n=self::user(get_current_user_id(),'DARES testmelding','Pushmeldingen zijn ingeschakeld.');return rest_ensure_response(['success'=>$n>0,'accepted'=>$n]);}
 static function user($uid,$title,$body,$tag='dares-piket'){global $wpdb;if(!self::opts()['enabled']||!$uid)return 0;$rows=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table().' WHERE user_id=%d',$uid));$n=0;foreach($rows as $r)if(self::send($r,$title,$body,$tag))$n++;return $n;}
 static function person($pid,$title,$body,$tag='dares-piket'){global $wpdb;$m=$wpdb->get_var($wpdb->prepare('SELECT user_id FROM '.Dares_Piket_Advanced::t('meta').' WHERE person_id=%d',$pid));return $m?self::user((int)$m,$title,$body,$tag):0;}
 static function der($r,$s){$len=strlen($s);if($len<128)return $r.chr($len).$s;return $r."\x81".chr($len).$s;}
 static function pub_pem($raw){return "-----BEGIN PUBLIC KEY-----\n".chunk_split(base64_encode(hex2bin('3059301306072a8648ce3d020106082a8648ce3d030107034200').$raw),64,"\n")."-----END PUBLIC KEY-----\n";}
 static function hkdf($ikm,$salt,$info,$size){$prk=hash_hmac('sha256',$ikm,$salt,true);$out='';$t='';$i=1;while(strlen($out)<$size){$t=hash_hmac('sha256',$t.$info.chr($i++),$prk,true);$out.=$t;}return substr($out,0,$size);}
 static function send($row,$title,$body,$tag){$k=self::keypair();if(!$k)return false;$clientPub=self::decode($row->p256dh);$auth=self::decode($row->auth);if(strlen($clientPub)!==65||strlen($auth)!==16)return false;$pub=openssl_pkey_get_public(self::pub_pem($clientPub));$server=openssl_pkey_new(['private_key_type'=>OPENSSL_KEYTYPE_EC,'curve_name'=>'prime256v1']);if(!$pub||!$server||!function_exists('openssl_pkey_derive'))return false;$shared=openssl_pkey_derive($pub,$server,32);$details=openssl_pkey_get_details($server);$serverPub="\x04".$details['ec']['x'].$details['ec']['y'];$secret=self::hkdf($shared,$auth,"WebPush: info\0".$clientPub.$serverPub,32);$salt=random_bytes(16);$key=self::hkdf($secret,$salt,"Content-Encoding: aes128gcm\0",16);$nonce=self::hkdf($secret,$salt,"Content-Encoding: nonce\0",12);$data=wp_json_encode(['title'=>wp_strip_all_tags($title),'body'=>wp_strip_all_tags($body),'url'=>Dares_Piket_PWA::endpoint('app'),'tag'=>sanitize_key($tag)]);$plain=$data."\x02";$cipher=openssl_encrypt($plain,'aes-128-gcm',$key,OPENSSL_RAW_DATA,$nonce,$authTag);if($cipher===false)return false;$record=$salt.pack('N',4096).chr(strlen($serverPub)).$serverPub.$cipher.$authTag;$endpoint=$row->endpoint;$origin=wp_parse_url($endpoint,PHP_URL_SCHEME).'://'.wp_parse_url($endpoint,PHP_URL_HOST);$token=self::jwt($k,$origin);if(!$token)return false;$headers=['Content-Type'=>'application/octet-stream','Content-Encoding'=>'aes128gcm','TTL'=>'3600','Authorization'=>'vapid t='.$token.', k='.$k['public']];$response=wp_safe_remote_post($endpoint,['timeout'=>12,'redirection'=>0,'headers'=>$headers,'body'=>$record,'limit_response_size'=>1024]);if(is_wp_error($response))return false;$status=wp_remote_retrieve_response_code($response);if(in_array($status,[404,410],true)){global $wpdb;$wpdb->delete(self::table(),['id'=>$row->id]);}return in_array($status,[200,201,202],true);}
 static function jwt($k,$aud){$header=self::b64(wp_json_encode(['typ'=>'JWT','alg'=>'ES256']));$payload=self::b64(wp_json_encode(['aud'=>$aud,'exp'=>time()+3600,'sub'=>'mailto:'.(is_email(self::opts()['contact'])?self::opts()['contact']:get_option('admin_email'))]));$msg=$header.'.'.$payload;if(!openssl_sign($msg,$der,$k['private'],OPENSSL_ALGO_SHA256))return false;$pos=2;$nums=[];for($i=0;$i<2;$i++){if(!isset($der[$pos])||ord($der[$pos++])!==2)return false;$len=ord($der[$pos++]);$nums[]=str_pad(ltrim(substr($der,$pos,$len),"\0"),32,"\0",STR_PAD_LEFT);$pos+=$len;}return $msg.'.'.self::b64(implode('',$nums));}
 static function tick(){if(!self::opts()['enabled'])return;global $wpdb;$o=self::opts();$now=Dares_Piketrooster::now();$until=current_datetime()->modify('+'.$o['reminder_hours'].' hours')->format('Y-m-d H:i:s');$t=Dares_Piketrooster::tables();$up=$wpdb->get_results($wpdb->prepare("SELECT id,person_id,start_at,end_at FROM {$t['shifts']} WHERE start_at>%s AND start_at<=%s LIMIT 100",$now,$until));foreach($up as $s){$key='push-reminder-'.$s->id.'-'.$s->start_at;if($o['reminder'])self::once($key,(int)$s->person_id,'DARES: piket binnenkort','Je piket begint '.$s->start_at.'. Bevestig je dienst in het portaal.');}if($o['start']){$active=Dares_Piketrooster::global_current();if($active)self::once('push-start-'.$active->id.'-'.$active->start_at,(int)$active->person_id,'DARES: je hebt nu piket','Je piketdienst is begonnen. Bevestig je dienst in het portaal.');}}
 static function once($key,$pid,$title,$body){$hash=hash('sha256',$key);if(get_transient('dares_push_'.$hash))return; $count=self::person($pid,$title,$body,$key);if($count)set_transient('dares_push_'.$hash,1,45*DAY_IN_SECONDS);}
 static function queue($type,$pid,$title,$body){$o=self::opts();if(!empty($o[$type]))self::person($pid,$title,$body,$type.'-'.time());}
 static function send_event($type,$pid,$title,$body){self::queue($type,$pid,$title,$body);}
}
